using V=arkjson::Value;
const V& get(const V& v,const char* key){const auto* p=v.find(key);if(!p)throw std::runtime_error(std::string("Geometry graph requires ")+key);return *p;}
std::string text(const V& v,const char* key){const auto& p=get(v,key);if(p.t!=V::Str||p.str.empty())throw std::runtime_error(std::string("Geometry graph requires text ")+key);return p.str;}
u64 integer(const V& v,bool zero=false){if(v.t!=V::Num||!std::isfinite(v.num)||v.num<(zero?0:1)||v.num>9007199254740991.||v.num!=std::floor(v.num))throw std::runtime_error("Geometry graph requires an exact nonnegative ID/index");return (u64)v.num;}
V json(const char* value){V out;if(!arkjson::parse(value,out))throw std::runtime_error("Invalid built-in geometry node recipe");return out;}
struct Recipe {const char* key;const char* name;const char* type;const char* domain;const char* input;size_t minimum,maximum;const char* p;const char* native;};
