V geometryNodeCommands078B(const Document& doc,const V& edit){
 allowed(edit,{"op","recipe","name","node","source","target","input","inputs","parameters","native"});const auto action=text(edit,"op");V command=V::makeObj();
 if(action=="add"){const auto key=text(edit,"recipe");const Recipe* found=nullptr;for(const auto& recipe:recipes)if(recipe.key==key)found=&recipe;if(!found)throw std::runtime_error("Unknown geometry node recipe; inspect geometry_graph catalog");const auto& r=*found;auto inputs=inputIds(edit.find("inputs"));checkInputs(doc,0,inputs,{r.input,r.minimum,r.maximum,true});command.set("op",V::makeStr("feature.add"));command.set("type",V::makeStr(r.type));command.set("name",V::makeStr(edit.find("name")?text(edit,"name"):r.name));V parameters=json(r.p);if(auto* supplied=edit.find("parameters")){if(supplied->t!=V::Obj)throw std::runtime_error("Node parameters must be an object");for(const auto& p:supplied->obj){if(!parameters.find(p.first.c_str()))throw std::runtime_error("Unknown recipe parameter: "+p.first);parameters.set(p.first,p.second);}}command.set("p",std::move(parameters));const bool mesh=std::string(r.type).rfind("mesh_",0)==0;if(mesh){if(edit.find("native"))throw std::runtime_error("Mesh nodes use parameters and explicit mesh inputs, not a native source object");}else{V spec=edit.find("native")?get(edit,"native"):json(r.native);if(spec.t!=V::Obj)throw std::runtime_error("Native node source must be an object");if(!spec.obj.empty())command.set("native",std::move(spec));}command.set("inputs",ids(inputs));}
 else if(action=="link"||action=="disconnect"){const auto target=integer(get(edit,"target"));const auto* f=doc.find(target);if(!f)throw std::runtime_error("Geometry target node does not exist");auto inputs=f->inputs;const auto slot=integer(get(edit,"input"),true);if(action=="link"){if(slot>inputs.size())throw std::runtime_error("Geometry input slots must remain contiguous");const auto source=integer(get(edit,"source"));if(slot==inputs.size())inputs.push_back(source);else inputs[(size_t)slot]=source;}else{if(slot>=inputs.size())throw std::runtime_error("Geometry input is not connected");inputs.erase(inputs.begin()+(size_t)slot);}checkInputs(doc,target,inputs,ports(*f));command.set("op",V::makeStr("feature.edit"));command.set("id",V::makeNum((double)target));command.set("inputs",ids(inputs));}
 else if(action=="edit"||action=="remove"){const auto target=integer(get(edit,"node"));const auto* f=doc.find(target);if(!f)throw std::runtime_error("Geometry node does not exist");command.set("op",V::makeStr(action=="remove"?"feature.remove":"feature.edit"));command.set("id",V::makeNum((double)target));if(action=="edit"){if(auto* value=edit.find("name"))command.set("name",*value);if(auto* value=edit.find("parameters"))command.set("p",*value);if(auto* value=edit.find("native"))command.set("native",*value);if(command.obj.size()==2)throw std::runtime_error("Node edit must supply name, parameters or native source");}}
 else throw std::runtime_error("Geometry graph edit op must be add, edit, link, disconnect or remove");
 V commands=V::makeArr();commands.arr.push_back(std::move(command));return commands;
}
bool callGeometryGraphTool078B(AgentSession& session,const std::string& tool,const V& args,V& out){if(tool!="geometry_graph")return false;allowed(args,{"action","expected_revision","edit","ids","limit","cursor"});const auto action=text(args,"action");if(action!="inspect"&&(args.find("ids")||args.find("limit")||args.find("cursor")))throw std::runtime_error("Geometry graph ids/limit/cursor are inspect-only");if(auto* expected=args.find("expected_revision");expected&&integer(*expected,true)!=session.revision)throw std::runtime_error("Revision conflict; inspect the current geometry graph before editing");if(action=="catalog"){out=V::makeObj();out.set("revision",V::makeNum((double)session.revision));out.set("recipes",geometryNodeCatalog078B());return true;}if(action=="inspect"){if(args.find("edit"))throw std::runtime_error("Geometry inspect does not accept an edit");out=inspectGeometryGraph078B(session.document,session.revision,args);return true;}if(action!="prepare")throw std::runtime_error("Geometry graph action must be inspect, catalog or prepare");integer(get(args,"expected_revision"),true);V apply=V::makeObj();apply.set("commands",geometryNodeCommands078B(session.document,get(args,"edit")));apply.set("expected_revision",V::makeNum((double)session.revision));apply.set("detail",V::makeStr("changes"));const auto result=session.call("doc_preview",apply);const auto& checked=get(result,"structuredContent");if(get(result,"isError").b||!get(checked,"valid").b||!checked.find("candidate_id"))throw std::runtime_error("Geometry node preview rejected: "+checked.dump());out=checked;out.set("publication",V::makeStr("doc_apply candidate_id + expected_revision"));return true;}
void appendGeometryGraphTools078B(V& list){V tool=V::makeObj();tool.set("name",V::makeStr("geometry_graph"));tool.set("description",V::makeStr("Inspect bounded geometry-node metadata (ids, limit1..64, default16) or its typed recipe catalog. Follow next_call for current-source pages; context_call retrieves adjacent graph context. Native source and mesh buffers are omitted. prepare validates add/edit/link/disconnect/remove against current feature history and exact geometry, returning an isolated candidate for doc_apply. Mesh/surface/solid domains are distinct; sampling exact geometry requires the explicit sample_to_mesh node. Invalid/stale/cyclic/forward/incomplete links reject without changing the document."));tool.set("inputSchema",json(R"({"type":"object","additionalProperties":false,"properties":{"action":{"type":"string","enum":["inspect","catalog","prepare"]},"expected_revision":{"type":"integer","minimum":0},"ids":{"type":"array","minItems":1,"maxItems":64,"uniqueItems":true,"items":{"type":"integer","minimum":1}},"limit":{"type":"integer","minimum":1,"maximum":64},"cursor":{"type":"object","additionalProperties":false,"properties":{"source_sha256":{"type":"string","pattern":"^[0-9a-f]{64}$"},"revision":{"type":"integer","minimum":0},"selection_sha256":{"type":"string","pattern":"^[0-9a-f]{64}$"},"offset":{"type":"integer","minimum":0}},"required":["source_sha256","revision","selection_sha256","offset"]},"edit":{"type":"object","additionalProperties":false,"properties":{"op":{"type":"string","enum":["add","edit","link","disconnect","remove"]},"recipe":{"type":"string"},"name":{"type":"string"},"node":{"type":"integer","minimum":1},"source":{"type":"integer","minimum":1},"target":{"type":"integer","minimum":1},"input":{"type":"integer","minimum":0},"inputs":{"type":"array","items":{"type":"integer","minimum":1}},"parameters":{"type":"object"},"native":{"type":"object"}},"required":["op"]}},"required":["action"]})"));V annotations=V::makeObj();annotations.set("readOnlyHint",V::makeBool(false));tool.set("annotations",annotations);list.arr.push_back(std::move(tool));}
